const rows = $input.all().map(i => i.json);
const get = n => (rows.find(r => r.name === n) || {}).value;
const token = String(get('telegram_bot_token') || '').trim();
const offset = Number(get('telegram_offset') || 0);
// Without a token the workflow cannot work, so this must raise an alert instead of passing silently.
if (!token) {
  throw new Error('Nema telegram_bot_token u data table stan_hunter_kv');
}
return [{ json: { token: token, offset: offset } }];

const items = $input.all();
const ndjson = items.map(i => JSON.stringify(i.json)).join('\n');
const metadata = {
  configuration: {
    load: {
      destinationTable: { projectId: 'stan-hunter', datasetId: 'stan_hunter', tableId: 'listings' },
      sourceFormat: 'NEWLINE_DELIMITED_JSON',
      writeDisposition: 'WRITE_APPEND',
      ignoreUnknownValues: true
    }
  }
};
return [{ json: { metadata, ndjson, count: items.length } }];

// GetUpdates error output: classify the error. The raw error and input item contain the token, so only this summary is passed on.
const raw = $json.error;
const e = typeof raw === 'string' ? { message: raw } : (raw ?? {});
const d = $json.details ?? {};
const fromMessage = String(e.message ?? '').match(/^(\d{3})\b/);
const status = Number(e.statusCode ?? e.status ?? d.httpCode ?? e.httpCode ?? e.response?.status ?? (fromMessage ? fromMessage[1] : NaN)) || null;
// No HTTP status = network error (DNS, timeout, offline).
const transient = status === null || status >= 500 || status === 429;
const description = String(d.body?.description ?? d.description ?? e.error?.description ?? '')
  .replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***')
  .slice(0, 200);
return { json: { status, code: typeof e.code === 'string' ? e.code : null, transient, description } };

// Commands: /oglas <text> → always the FB flow; /top or /pitaj <question> → always a database query; /start, /help and others → help.
// Without a command, IsShortMessage + Claude decide. The command is stripped from the text.
const t = String($json.message?.text ?? '').trim();
const m = t.match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
let force = 'auto';
let text = t;
if (m) {
  const cmd = m[1].toLowerCase();
  const rest = m[2].trim();
  if (cmd === 'oglas') { force = rest ? 'post' : 'help'; text = rest; }
  else if (cmd === 'top' || cmd === 'pitaj') { force = 'query'; text = rest || 'Daj mi 5 najboljih ponuda iz baze'; }
  else { force = 'help'; }
}
return { json: { ...$json, message: { ...$json.message, text }, force } };

// Click on "❌ N" under a /top reply: delete that listing from the table and remove the button.
// The sandbox has no DELETE → the table is recreated without that id (like the nightly Cleanup, which also takes the backup).
const cq = $json.callback_query;
const id = String(cq.data).slice(4);
const ok = /^[A-Za-z0-9_-]{1,60}$/.test(id);
const T = '`stan-hunter.stan_hunter.listings`';
const query = ok
  ? `CREATE OR REPLACE TABLE ${T} PARTITION BY DATE(upisano) AS SELECT * FROM ${T} WHERE id != '${id}' QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY upisano DESC) = 1`
  : 'SELECT 1';
const rows = cq.message?.reply_markup?.inline_keyboard ?? [];
const keyboard = rows.map(r => r.filter(b => b.callback_data !== cq.data)).filter(r => r.length);
return { json: { ok, id, cq_id: cq.id, chat_id: cq.message?.chat?.id, message_id: cq.message?.message_id, keyboard, request: { query, useLegacySql: false, location: 'EU', timeoutMs: 60000 } } };

// Screenshot of an FB post: Telegram sends several sizes of the same photo → take the largest (last in the array).
// An image sent as a file (uncompressed) arrives as a document with an image/* type.
const m = $json.message;
const photo = Array.isArray(m.photo) && m.photo.length ? m.photo[m.photo.length - 1] : null;
const file = photo ?? m.document;
return { json: { file_id: file.file_id, file_unique_id: file.file_unique_id, caption: String(m.caption ?? '').slice(0, 1000) } };

// Input for `FB post to listing`: image = true + the binary image in the data field.
// Telegram returns the file as application/octet-stream, but Claude only accepts image/jpeg|png|gif|webp → the type is set from the extension.
// The `directory` field holds a URL with the bot token → removed so the token never reaches the sub-workflow or its executions.
const b = { ...$input.item.binary.data };
const ext = String(b.fileExtension || b.fileName?.split('.').pop() || 'jpg').toLowerCase();
const TYPES = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp' };
b.mimeType = TYPES[ext] || 'image/jpeg';
delete b.directory;
b.fileName = 'screenshot.' + (TYPES[ext] ? ext : 'jpg');
return { json: { text: $('PreparePhoto').item.json.caption, url: '', grupa: 'fb', image: true }, binary: { data: b } };

// One reply per FB listing that was loaded: extracted fields + the 0–100 score from the view listings_scored (same formula as everywhere else).
// The score exists only after the load job is DONE (WaitForFbLoad); if the load failed, the reply says so instead of a score.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const load = $('WaitForFbLoad').all().at(-1)?.json ?? {};
const loadErr = load.status?.errorResult ? String(load.status.errorResult.message ?? load.status.errorResult.reason ?? 'greška').slice(0, 200)
  : load.status?.state !== 'DONE' ? 'upis nije potvrđen (BigQuery nije odgovorio)' : null;
const r = $input.first()?.json ?? {};
const fields = (r.schema?.fields || []).map(f => f.name);
const scores = {};
for (const row of r.rows || []) {
  const o = Object.fromEntries(row.f.map((c, i) => [fields[i], c.v]));
  scores[o.id] = { ocena: o.ocena === null ? null : Math.round(Number(o.ocena)), lok: o.lok === null ? null : Number(o.lok) };
}
return $('IsNewFlat').all().map(({ json: j }) => {
  const s = scores[j.id] || {};
  const lines = [
    `✅ <b>Dodato:</b> ${esc(j.naslov)}`,
    `🏠 ${j.cena ?? '?'} € · ${j.m2 ?? '?'} m² · ${j.sobe ?? '?'} soba`,
    s.ocena !== null && s.ocena !== undefined ? `⭐ <b>${s.ocena}</b>/100` : null,
    `📍 ${esc(j.naselje || '?')}, ${esc(j.opstina || '?')}${s.lok ? ` (lokacija ${s.lok}/5)` : ''}`,
    j.kvalitet !== null && j.kvalitet !== undefined ? `📸 Slike: ${j.kvalitet}/5${j.kvalitet_opis ? ' – ' + esc(j.kvalitet_opis) : ''}` : null,
    `🐾 Ljubimci: ${esc(j.kucni_ljubimci)} · 💶 Depozit: ${j.depozit_eur ?? '?'} €`,
    `💼 Provizija: ${esc(j.provizija ?? 'nije navedena')} · Režije: ${j.rezije_eur ?? '?'} €`,
    `⚠️ ${j.sumnjiv_oglas ? esc(j.sumnjiv_razlog || 'proveri oglas') : 'ništa sumnjivo'}`,
    `🎯 Prolazi filter: ${j.prosao_filter ? 'da' : 'ne'}`,
    j.dup_id && j.dup_isti === false ? `🔎 Sličan oglas na ${esc(j.dup_izvor)}, ali nije isti stan: ${esc(j.dup_razlog || '')}` : null,
    j.dup_id && j.dup_isti === null ? `🔎 Možda isti stan kao <a href="${esc(j.dup_url)}">${esc(j.dup_izvor)} oglas</a> (nisam mogao da uporedim slike)` : null,
    loadErr ? `❗ Upis u bazu nije uspeo: ${esc(loadErr)}` : null
  ].filter(Boolean);
  return { json: { text: lines.join('\n') } };
});
